  multiple: false,
  loop: true,
  disableChevronRotation: false,
  disableCollapse: false,
  chevronPosition: 'right',
  variant: 'default',
  chevronSize: 'auto',
  chevronIconSize: 16,
  keepMountedMode: 'activity',
} satisfies Partial<AccordionProps>;

