  })
);

export const Accordion = genericFactory<AccordionFactory>((_props) => {
  const props = useProps('Accordion', defaultProps as any, _props);
  const {
    classNames,
    className,
    style,
    styles,
    unstyled,
    vars,
    children,
    multiple,
    value,
    defaultValue,
    onChange,
    id,
    loop,
    transitionDuration,
    disableChevronRotation,
    disableCollapse,
    chevronPosition,
    chevronSize,
    order,
    chevron,
    variant,
    radius,
    chevronIconSize,
    attributes,
    keepMounted,
    keepMountedMode,
    ...others
