    screen.getByText('Trigger One').focus();
    fireEvent.keyDown(document.activeElement!, { key: 'ArrowDown' });
    expect(screen.getByText('Trigger Two')).toHaveFocus();

    await act(async () => {
      rerender(<List promise={pendingPromise} />);
