    expect(screen.getByText('loading')).toBeInTheDocument();

    screen.getByText('Trigger One').focus();
    fireEvent.keyDown(document.activeElement!, { key: 'ArrowDown' });
    expect(screen.getByText('Trigger Three')).toHaveFocus();
